"""Deterministic documentation snapshot generated by the real Prompt v1 builder."""

import argparse
import hashlib
from pathlib import Path

from j_gamelqa.io import load_glossary
from j_gamelqa.prompts import (
    CONTEXT_INPUT_FIELDS,
    LLMInputMode,
    build_evaluator_prompt,
)


PROJECT_ROOT = Path(__file__).resolve().parents[2]
PROMPT_VERSION = "v1"
DEMO_RECORD = {
    "string_id": "DOC_DEMO_001",
    "source_zh": "队长，{device_name}旁的传送门已经启动。",
    "target_ja": "隊長、{device_name}のそばにある転送門は起動しました。",
    "string_type": "dialogue",
    "speaker": "整备员真琴",
    "addressee": "远征队长",
    "scene": "飞艇甲板",
    "relationship": "整备员向直属队长进行正式报告",
    "context_before": "队长询问撤离装置是否可以使用。",
    "context_after": "队员们开始向传送门集合。",
    "max_length": "40",
}


def _sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest().upper()


def build_snapshot_prompts(
    glossary: list[dict[str, str]],
) -> dict[str, str]:
    """Generate both examples by calling the production Prompt v1 builder."""
    return {
        "without_context": build_evaluator_prompt(
            DEMO_RECORD,
            glossary,
            LLMInputMode.WITHOUT_CONTEXT,
        ),
        "with_context": build_evaluator_prompt(
            DEMO_RECORD,
            glossary,
            LLMInputMode.WITH_CONTEXT,
        ),
    }


def render_prompt_snapshot(glossary: list[dict[str, str]]) -> str:
    prompts = build_snapshot_prompts(glossary)
    context_fields = ", ".join(f"`{field}`" for field in CONTEXT_INPUT_FIELDS)
    return (
        "# Prompt v1 Snapshot\n\n"
        "- Prompt version: `v1`\n"
        "- Generator: `j_gamelqa.prompts.build_evaluator_prompt`\n"
        "- Sample source: dedicated synthetic documentation demo; not DEV or Test data\n"
        f"- Without Context SHA-256: `{_sha256_text(prompts['without_context'])}`\n"
        f"- With Context SHA-256: `{_sha256_text(prompts['with_context'])}`\n\n"
        "This file is generated from the real shared Prompt Builder. It is a readable "
        "snapshot of the exact strings supplied to the provider, not a manually "
        "rewritten approximation.\n\n"
        "## Shared Prompt v1\n\n"
        "Both modes use the same Role and task, 22-type issue taxonomy, evaluation "
        "rules, and required JSON output contract. The only intended difference is "
        "the input payload.\n\n"
        "## Without Context Example\n\n"
        "~~~text\n"
        f"{prompts['without_context']}\n"
        "~~~\n\n"
        "## With Context Example\n\n"
        f"This mode adds exactly: {context_fields}.\n\n"
        "~~~text\n"
        f"{prompts['with_context']}\n"
        "~~~\n"
    )


def write_prompt_snapshot(
    output_path: str | Path,
    glossary_path: str | Path,
) -> Path:
    destination = Path(output_path)
    if destination.exists():
        raise FileExistsError(f"prompt snapshot already exists: {destination}")
    glossary = load_glossary(glossary_path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(render_prompt_snapshot(glossary), encoding="utf-8")
    return destination


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate the deterministic Prompt v1 documentation snapshot."
    )
    parser.add_argument(
        "--glossary",
        type=Path,
        default=PROJECT_ROOT / "data" / "glossary.csv",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=PROJECT_ROOT / "docs" / "prompt_v1_snapshot.md",
    )
    args = parser.parse_args()
    print(write_prompt_snapshot(args.output, args.glossary))


if __name__ == "__main__":
    main()
